}
/* 悬停气泡（浅入浅出） */
.link::after {
  content: attr(data-title);
  position: absolute;
  bottom: calc(100% + 8px);
  left: 50%;
  transform: translateX(-50%) translateY(4px);
  background: var(--text);
  color: var(--bg);
  font-size: 12px;
  padding: 4px 10px;
  border-radius: 6px;
  white-space: nowrap;
  opacity: 0;
  pointer-events: none;       /* 气泡不拦截鼠标，hover 不闪烁 */
  transition: opacity 0.2s, transform 0.2s;
}
/* 气泡下方的小箭头 */
.link::before {
  content: '';
  position: absolute;
  bottom: calc(100% + 3px);
  left: 50%;
  transform: translateX(-50%) translateY(4px);
  border: 5px solid transparent;
  border-top-color: var(--text);
  opacity: 0;
  pointer-events: none;
  transition: opacity 0.2s, transform 0.2s;
}
.link:hover::after,
.link:hover::before {
  opacity: 1;
  transform: translateX(-50%) translateY(0);
}
.link:hover {
  text-decoration: underline;
}
